// Isolated synthetic Worker for the seed-sync upgrade qualification. Never imported by production.
// POST /<prefix>/seed-legacy once on the pre-0052 schema; POST /<prefix>/verify once after 0052 and 0053 are applied. A replay of either returns 409.
import {seedLegacy,verifyUpgrade} from './upgrade.js';
import {SeedCipher} from '../../src/seed-cipher.js';
const used=new Set();
// The AES key is a per-run synthetic scratch value generated by the workflow, so both requests (possibly different isolates) share one key. It never leaves the Worker.
const cipherFor=async env=>{const raw=Uint8Array.from(atob(env.FIXTURE_KEY_B64),c=>c.charCodeAt(0));if(raw.length!==32)throw Error('fixture key missing');
 return new SeedCipher({keys:new Map([['t',await crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['encrypt','decrypt'])]]),activeKeyId:'t'});};
export default {
  async fetch(request,env){
    const u=new URL(request.url),prefix='/'+env.FIXTURE_PREFIX,op=u.pathname.slice(prefix.length);
    if(u.pathname===prefix+'/ready'&&request.method==='GET')return Response.json({synthetic:true,ready:true});
    if(!u.pathname.startsWith(prefix+'/')||request.method!=='POST'||!['/seed-legacy','/verify'].includes(op))return new Response(null,{status:404});
    if(used.has(op))return new Response(null,{status:409});used.add(op);
    try{const cipher=await cipherFor(env);return Response.json(op==='/seed-legacy'?await seedLegacy(env.DB,cipher):await verifyUpgrade(env.DB,cipher));}
    catch(e){return Response.json({synthetic:true,pass:false,fatal:String(e?.message??e).slice(0,400)},{status:500});}
  }
};
